const express=require('express'),router=express.Router(),perksController=require('../controllers/perksController.min.js'),{onlyAdminAuth}=require('../middlewares/auth.min.js'),cache=require('../route_cache.js'),FIVE_HOURS=18e3;router.post('/perks',onlyAdminAuth,perksController.create_perk);router.get('/perks',cache(FIVE_HOURS),perksController.get_perks);router.get('/admin-perks',onlyAdminAuth,perksController.get_admin_perks);router.get('/perks/:id',onlyAdminAuth,perksController.get_single_perk);router.delete('/perks/:id',onlyAdminAuth,perksController.delete_perk);router.put('/perks/:id',onlyAdminAuth,perksController.update_perk);module.exports=router; 